// Importer tests: a backup generated by the prototype's own code goes through the
// transform and into a real Postgres with the production migrations applied.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { createTestDb, createUser, as, one, all } from './helpers/db.mjs';
import { transformBackup, runImport, isPrototypeBackup } from '../scripts/lib/transform.mjs';

const backup = JSON.parse(await readFile(new URL('./fixtures/prototype-backup.json', import.meta.url), 'utf8'));

function pgWriter(db, uploads = []) {
  return {
    async countImportedJobs() { return (await one(db, `select count(*)::int as n from jobs where legacy_id is not null`)).n; },
    async deleteAll(t) { await db.query(`delete from ${t}`); },
    async insert(t, rows) {
      for (const r of rows) {
        const cols = Object.keys(r);
        const vals = cols.map(c => (r[c] !== null && typeof r[c] === 'object' ? JSON.stringify(r[c]) : r[c]));
        await db.query(`insert into ${t} (${cols.join(', ')}) values (${cols.map((_, i) => `$${i + 1}`).join(', ')})`, vals);
      }
    },
    async updateSettings(row) {
      const cols = Object.keys(row);
      await db.query(`update settings set ${cols.map((c, i) => `${c} = $${i + 1}`).join(', ')} where id = 1`, cols.map(c => row[c]));
    },
    async upload(path, buffer, type) { uploads.push({ path, size: buffer.length, type }); },
    async syncSequences() { await db.query(`select sync_number_sequences()`); },
  };
}

async function freshDbWithTeam() {
  const db = await createTestDb();
  const owner = await createUser(db, 'owner@example.com', 'Olivia Owner');
  const pat = await createUser(db, 'pat@example.com', 'Pat Office');
  await as(db, owner, q => q.query(`update profiles set role = 'office', active = true, full_name = 'Pat Office' where id = $1`, [pat]));
  const profiles = await all(db, `select id, full_name, email from profiles where active`);
  return { db, owner, pat, profiles };
}

test('recognises prototype backups and rejects other files', () => {
  assert.ok(isPrototypeBackup(backup));
  assert.equal(isPrototypeBackup({ app: 'other' }), false);
  assert.throws(() => transformBackup({ hello: 1 }), /not a Roofing CRM prototype backup/);
});

test('default import keeps your own records and leaves out sample data', async () => {
  const { db, owner, pat, profiles } = await freshDbWithTeam();
  const result = transformBackup(backup, { profiles });
  const uploads = [];
  await runImport(result, pgWriter(db, uploads));

  const jobs = await all(db, `select number, name, stage, rep_id, type from jobs`);
  assert.deepEqual(jobs.map(j => j.name), ['Lee Repair']);
  assert.equal(jobs[0].number, 1013);
  assert.equal(jobs[0].stage, 'estimate');
  assert.equal(jobs[0].rep_id, pat, 'rep matched to the login with the same name');

  assert.equal((await all(db, `select id from contacts`)).length, 1);
  const doc = await one(db, `select kind, number, status, items from documents`);
  assert.equal(doc.kind, 'estimate');
  assert.deepEqual(doc.items, [{ desc: 'Pipe boot', qty: 3, unit: 'EA', price: 45 }]);

  const ev = await one(db, `select e.title, c.name as crew from events e join crews c on c.id = e.crew_id`);
  assert.deepEqual(ev, { title: 'Repair', crew: 'Crew C' });
  assert.deepEqual((await all(db, `select name from crews`)).map(c => c.name), ['Crew C'], 'sample crews A and B left out');
  assert.equal((await one(db, `select assignee_id from tasks`)).assignee_id, null);
  assert.ok(result.warnings.some(w => w.includes('Order boots')), 'warns that a crew task became unassigned');

  assert.equal((await one(db, `select count(*)::int as n from templates`)).n, 10, 'templates replaced, not doubled');
  assert.equal((await one(db, `select count(*)::int as n from automation_rules`)).n, 8);
  assert.equal((await one(db, `select count(*)::int as n from catalog_items`)).n, 11);

  assert.equal(uploads.length, 1);
  assert.match(uploads[0].path, /^[0-9a-f-]{36}\/[0-9a-f-]{36}\.jpg$/);
  assert.equal(uploads[0].type, 'image/jpeg');
  assert.equal((await one(db, `select caption from photos`)).caption, 'Cracked boot');

  const notes = await all(db, `select text from job_activity order by at`);
  assert.ok(notes.some(n => n.text === 'Customer prefers mornings'));
  assert.equal((await one(db, `select count(*)::int as n from outbox`)).n, 0, 'importing does not fire new follow-up emails');

  // Numbering continues after the imported records.
  await as(db, owner, async q => {
    const j = await one(q, `insert into jobs (name) values ('Next job') returning number`);
    assert.equal(j.number, 1014);
    const est = await one(q, `insert into documents (kind, job_id) select 'estimate', id from jobs where name = 'Next job' returning number`);
    assert.equal(est.number, doc.number + 1);
  });

  await assert.rejects(runImport(result, pgWriter(db)), /already has imported jobs/);
});

test('--include-sample brings everything across with totals intact', async () => {
  const { db, profiles } = await freshDbWithTeam();
  const result = transformBackup(backup, { includeSample: true, profiles });
  await runImport(result, pgWriter(db));

  assert.equal((await one(db, `select count(*)::int as n from jobs`)).n, 13);
  assert.equal((await one(db, `select count(*)::int as n from contacts`)).n, 13);
  assert.deepEqual((await all(db, `select name from crews order by name`)).map(c => c.name), ['Crew A', 'Crew B', 'Crew C']);
  assert.ok(result.warnings.some(w => w.includes('Dana Whitfield')), 'unmatched reps are reported');

  const paid = await one(db, `select j.stage, private.document_balance(d.id) as balance from documents d join jobs j on j.id = d.job_id
    where d.kind = 'invoice' and j.stage = 'paid'`);
  assert.equal(Number(paid.balance), 0, 'paid invoice has no balance after import');
  const partial = await one(db, `select private.document_balance(d.id) as balance, private.document_total(d.items, d.tax_rate) as total
    from documents d join jobs j on j.id = d.job_id where d.kind = 'invoice' and j.stage = 'invoiced'`);
  assert.ok(Number(partial.balance) > 0 && Number(partial.balance) < Number(partial.total));

  const inv = await one(db, `select from_id from documents where kind = 'invoice' limit 1`);
  assert.ok(inv.from_id, 'invoice still links to its estimate');
  const claim = await one(db, `select insurance from jobs where stage = 'progress'`);
  assert.equal(claim.insurance.supplements.length, 1);
  assert.equal((await one(db, `select count(*)::int as n from outbox where status = 'scheduled'`)).n, 4);
});
